import React from "react";
import "../style/Navbar.css";

const Navbar = (props) => {
  return (
    <div
      className="con-nav start-50 top-0 translate-middle-x"
      ref={props.navRef}
    >
      <div className="text-center">
        <a
          className="custom-nav-text"
          href="/"
          onClick={(e) => {
            e.preventDefault();
            props.goto("home");
          }}
        >
          Home
        </a>
        <a
          className="custom-nav-text"
          href="/"
          onClick={(e) => {
            e.preventDefault();
            props.goto("about");
          }}
        >
          About
        </a>
        <a
          className="custom-nav-text"
          href="/"
          onClick={(e) => {
            e.preventDefault();
            props.goto("skills");
          }}
        >
          Skills
        </a>
        <a
          className="custom-nav-text"
          href="/"
          onClick={(e) => {
            e.preventDefault();
            props.goto("project");
          }}
        >
          Project
        </a>
        <a
          className="custom-nav-text"
          href="/"
          onClick={(e) => {
            e.preventDefault();
            props.goto("contact");
          }}
        >
          Contact
        </a>
      </div>
    </div>
  );
};

export default Navbar;
